const { fail } = require('../utils/response');

/**
 * Auth middleware: Verify JWT token and attach user info to request
 */
function authMiddleware(req, res, next) {
  const token = getTokenFromHeader(req);
  if (!token) {
    return res.status(401).json(fail('请先登录', 401));
  }

  const decoded = verifyToken(token);
  if (!decoded) {
    return res.status(401).json(fail('登录已过期，请重新登录', 401));
  }

  req.user = decoded;
  next();
}

/**
 * Admin middleware: Check if the authenticated user is an admin
 */
function adminMiddleware(req, res, next) {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json(fail('权限不足', 403));
  }
  next();
}

module.exports = { authMiddleware, adminMiddleware };
