{"content": "const bcrypt = require('bcryptjs');
const { getDb } = require('../config/db');
const { generateToken } = require('../utils/token');
const { success, fail } = require('../utils/response');

const authController = {
  // POST /api/auth/register
  register(req, res) {
    try {
      const { username, password, email } = req.body;

      if (!username || !password) {
        return res.status(400).json(fail('用户名和密码不能为空'));
      }

      const db = getDb();

      // Check if username already exists
      const existing = db.prepare('SELECT id FROM users WHERE username = ?').get(username);
      if (existing) {
        return res.status(400).json(fail('用户名已存在'));
      }

      // Hash password
      const hashedPassword = bcrypt.hashSync(password, 10);

      // Create user
      const result = db.prepare(
        'INSERT INTO users (username, password, email, role) VALUES (?, ?, ?, ?)'
      ).run(username, hashedPassword, email || null, 'user');

      const token = generateToken({ id: result.lastInsertRowid, username, role: 'user' });

      res.status(201).json(success({
        id: result.lastInsertRowid,
        username,
        email: email || null,
        role: 'user',
        token,
      }, '注册成功'));
    } catch (err) {
      console.error('Register error:', err);
      res.status(500).json(fail('注册失败'));
    }
  },

  // POST /api/auth/login
  login(req, res) {
    try {
      const { username, password } = req.body;

      if (!username || !password) {
        return res.status(400).json(fail('用户名和密码不能为空'));
      }

      const db = getDb();
      const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username);

      if (!user) {
        return res.status(401).json(fail('用户名或密码错误'));
      }

      if (!bcrypt.compareSync(password, user.password)) {
        return res.status(401).json(fail('用户名或密码错误'));
      }

      if (user.status === 0) {
        return res.status(403).json(fail('账户已被禁用'));
      }

      const token = generateToken({ id: user.id, username: user.username, role: user.role });

      res.json(success({
        id: user.id,
        username: user.username,
        email: user.email,
        phone: user.phone,
        role: user.role,
        avatar: user.avatar,
        token,
      }, '登录成功'));
    } catch (err) {
      console.error('Login error:', err);
      res.status(500).json(fail('登录失败'));
    }
  },

  // GET /api/auth/me
  getMe(req, res) {
    try {
      const token = require('../utils/token').getTokenFromHeader(req);
      if (!token) {
        return res.status(401).json(fail('请先登录', 401));
      }

      const decoded = require('../utils/token').verifyToken(token);
      if (!decoded) {
        return res.status(401).json(fail('登录已过期', 401));
      }

      const db = getDb();
      const user = db.prepare('SELECT id, username, email, phone, role, avatar, status, created_at FROM users WHERE id = ?').get(decoded.id);

      if (!user) {
        return res.status(404).json(fail('用户不存在'));
      }

      res.json(success(user));
    } catch (err) {
      console.error('GetMe error:', err);
      res.status(500).json(fail('获取用户信息失败'));
    }
  },
};

module.exports = authController;", "path": "D:\cncodetest\ecommerce\server\src\controllers\authController.js"}
